async function openInAI(provider, prompt) {
  const encoded = encodeURIComponent(prompt);
  if (provider === "chatgpt") {
    window.open(`https://chatgpt.com/?prompt=${encoded}`, "_blank", "noopener,noreferrer");
    return;
  }
  if (provider === "claude") {
    window.location.href = `claude://claude.ai/new?q=${encoded}`;
    return;
  }
  if (provider === "claude-code") {
    window.open(`https://claude.ai/code?prompt=${encoded}`, "_blank", "noopener,noreferrer");
    return;
  }
  if (provider === "perplexity") {
    window.open(`https://www.perplexity.ai/search?q=${encoded}`, "_blank", "noopener,noreferrer");
    return;
  }
  const homeUrls = { gemini: "https://gemini.google.com/app" };
  await navigator.clipboard.writeText(prompt);
  window.open(homeUrls[provider], "_blank", "noopener,noreferrer");
}
